import{_ as i,o as s,c as d,ak as c}from"./chunks/framework.PDII-gUq.js";const g="/projects/H5S/en/latest/assets/image1.7XCjgd3O.webp",n="data:image/png;base64,",a="data:image/png;base64,",h="/projects/H5S/en/latest/assets/image1.iute6XWQ.webp",p="/projects/H5S/en/latest/assets/image2.CWEW0YgE.webp",A="/projects/H5S/en/latest/assets/image3.C1h6Nij3.webp",m="/projects/H5S/en/latest/assets/image3.D4QrOgNM.webp",l="/projects/H5S/en/latest/assets/image1.CbWfecpe.webp",r="/projects/H5S/en/latest/assets/image2.Bn3zoHkN.webp",t="data:image/png;base64,",u="/projects/H5S/en/latest/assets/image4.Ccvhza5r.webp",b="data:image/png;base64,",f="data:image/png;base64,",y="/projects/H5S/en/latest/assets/image7.LIFsFQOS.webp",x="/projects/H5S/en/latest/assets/image8.0AY9rZZw.webp",w="/projects/H5S/en/latest/assets/image9.HDETftOe.webp",v="/projects/H5S/en/latest/assets/image10.D3_s34qw.webp",e="/projects/H5S/en/latest/assets/image11.CLt6q1-o.webp",S="/projects/H5S/en/latest/assets/image12.DmboAVXp.webp",z="/projects/H5S/en/latest/assets/image13.DRwutfpP.webp",E="/projects/H5S/en/latest/assets/image14.7KS-yn9K.webp",C="/projects/H5S/en/latest/assets/image15.CffMT-hP.webp",V="/projects/H5S/en/latest/assets/image16.BFsHa_vJ.webp",k="/projects/H5S/en/latest/assets/image17.DGBUedmB.webp",X="/projects/H5S/en/latest/assets/image18.DixlaaPA.webp",O=JSON.parse('{"title":"2. Remote Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.Remote_Control.md","filePath":"docs/2.Remote_Control.md"}'),K={name:"docs/2.Remote_Control.md"};function W(q,o,B,R,U,P){return s(),d("div",null,[...o[0]||(o[0]=[c('<h1 id="_2-remote-control" tabindex="-1">2. Remote Control <a class="header-anchor" href="#_2-remote-control" aria-label="Permalink to &quot;2. Remote Control&quot;">​</a></h1><h2 id="_2-1-wireless-control" tabindex="-1">2.1 Wireless Control <a class="header-anchor" href="#_2-1-wireless-control" aria-label="Permalink to &quot;2.1 Wireless Control&quot;">​</a></h2><h3 id="_2-1-1-preparation" tabindex="-1">2.1.1 Preparation <a class="header-anchor" href="#_2-1-1-preparation" aria-label="Permalink to &quot;2.1.1 Preparation&quot;">​</a></h3><p>(1) The wireless receiver for the controller is pre-installed in the robot at the time of shipment. Please prepare two AAA batteries to power on the wireless controller.</p><p>(2) Remove the back cover of the wireless controller and insert the batteries. Make sure to insert the batteries with the correct polarity.</p><h3 id="_2-1-2-device-connection" tabindex="-1">2.1.2 Device Connection <a class="header-anchor" href="#_2-1-2-device-connection" aria-label="Permalink to &quot;2.1.2 Device Connection&quot;">​</a></h3><p>(1) Turn on both the robot and the wireless controller. The red and green LEDs on the controller will start flashing.</p><p>(2) Wait a few seconds until the robot and the controller are paired successfully. The green LED will remain on. If the connection fails, turn off both the robot and the controller, then repeat the steps above.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>Sleep Mode: If the controller is not connected to the robot within 30 seconds after being powered on, or if there is no user input for 5 minutes after connection, the controller will enter sleep mode. To wake the PS2 controller, simply press the <strong>&quot;START&quot;</strong> button.</p></div><h3 id="_2-1-3-button-instruction" tabindex="-1">2.1.3 Button Instruction <a class="header-anchor" href="#_2-1-3-button-instruction" aria-label="Permalink to &quot;2.1.3 Button Instruction&quot;">​</a></h3><img loading="lazy" height="410" width="800" src="'+g+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;">Button</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:left;">Stand at attention</td></tr><tr><td style="text-align:center;"><code>↑</code></td><td style="text-align:left;">Move Forward</td></tr><tr><td style="text-align:center;"><code>↓</code></td><td style="text-align:left;">Move Backward</td></tr><tr><td style="text-align:center;"><code>←</code></td><td style="text-align:left;">Single-leg Left Turn</td></tr><tr><td style="text-align:center;"><code>→</code></td><td style="text-align:left;">Single-leg Right Turn</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="45" width="48" src="'+n+'"></td><td style="text-align:left;">Forward Roll</td></tr><tr><td style="text-align:center;"><code>×</code></td><td style="text-align:left;">Backward Roll</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="31" width="31" src="'+a+'"></td><td style="text-align:left;">Push-up</td></tr><tr><td style="text-align:center;"><code>○</code></td><td style="text-align:left;">Sit-up</td></tr><tr><td style="text-align:center;"><code>L1</code></td><td style="text-align:left;">Waving</td></tr><tr><td style="text-align:center;"><code>R1</code></td><td style="text-align:left;">Bowing</td></tr><tr><td style="text-align:center;"><code>L2</code></td><td style="text-align:left;">Strafe left</td></tr><tr><td style="text-align:center;"><code>R2</code></td><td style="text-align:left;">Strafe right</td></tr><tr><td style="text-align:center;"><code>SELECT</code>+ <img loading="lazy" height="45" width="48" src="'+n+'"></td><td style="text-align:left;">Spread Wings</td></tr><tr><td style="text-align:center;"><code>SELECT</code> + <code>×</code></td><td style="text-align:left;">Squat</td></tr><tr><td style="text-align:center;"><code>SELECT</code>+ <img loading="lazy" height="31" width="31" src="'+a+'"></td><td style="text-align:left;">Laugh Out Loud</td></tr><tr><td style="text-align:center;"><code>SELECT</code> + <code>○</code></td><td style="text-align:left;">Street Dance</td></tr><tr><td style="text-align:center;"><code>SELECT</code> + <code>L1</code></td><td style="text-align:left;">Gangnam Style Dance</td></tr><tr><td style="text-align:center;"><code>SELECT</code> + <code>R1</code></td><td style="text-align:left;">Apple Dance</td></tr><tr><td style="text-align:center;"><code>SELECT</code> + <code>L2</code></td><td style="text-align:left;">La Song Dance</td></tr><tr><td style="text-align:center;"><code>SELECT</code> + <code>R2</code></td><td style="text-align:left;">Cool Dance</td></tr></tbody></table><p id="anchor_2_2"></p><h2 id="_2-2-app-installation-and-connection" tabindex="-1">2.2 APP Installation and Connection <a class="header-anchor" href="#_2-2-app-installation-and-connection" aria-label="Permalink to &quot;2.2 APP Installation and Connection&quot;">​</a></h2><h3 id="_2-2-1-app-installation" tabindex="-1">2.2.1 APP Installation <a class="header-anchor" href="#_2-2-1-app-installation" aria-label="Permalink to &quot;2.2.1 APP Installation&quot;">​</a></h3><p>iOS users: Search for <a href="https://apps.apple.com/us/app/wonderbot-robot/id1519146341" target="_blank" rel="noreferrer">Wonderbot</a> in the App Store to download, or go to the Appendix to find the <strong>Wonderbot</strong> installation package and install it on your phone.</p><p>Android users: You can find the <a href="https://play.google.com/store/apps/details?id=com.Wonder.bot" target="_blank" rel="noreferrer">Wonderbot</a> installation package in the same directory as this section or in the Appendix, then install it on your phone.</p><h3 id="_2-2-2-app-connection" tabindex="-1">2.2.2 APP Connection <a class="header-anchor" href="#_2-2-2-app-connection" aria-label="Permalink to &quot;2.2.2 APP Connection&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Ensure that both Bluetooth and Location Services are enabled in your phone&#39;s settings before launching the app.</p></li><li><p>Do not pair the device manually via system Bluetooth settings. Instead, use the Bluetooth button within the app to initiate pairing and connection.</p></li></ul></div><p>(1) Turn on the robot and open the mobile APP. You should see the main interface as shown below.</p><img loading="lazy" height="601" width="1280" src="'+h+'" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the displayed interface is different, tap the icon <img loading="lazy" height="33" width="35" src="'+p+'"> of the current page, then tap <strong>Robot</strong> and select <strong>RoboSoul</strong>.</p></div><img loading="lazy" height="596" width="1269" src="'+A+'" class="common_img"><p>(2) Tap the Bluetooth icon at the top to enter device search mode. Wait for few seconds, then select the device with the Bluetooth name <strong>&quot;Robo-Soul&quot;</strong>.</p><img loading="lazy" height="469" width="1000" src="'+m+'" class="common_img"><p>(3) Once connected successfully, the Bluetooth icon will remain solid and the robot&#39;s battery level will be displayed in the top-left corner of the screen.</p><h2 id="_2-3-app-user-guide" tabindex="-1">2.3 APP User Guide <a class="header-anchor" href="#_2-3-app-user-guide" aria-label="Permalink to &quot;2.3 APP User Guide&quot;">​</a></h2><h3 id="_2-3-1-getting-started" tabindex="-1">2.3.1 Getting Started <a class="header-anchor" href="#_2-3-1-getting-started" aria-label="Permalink to &quot;2.3.1 Getting Started&quot;">​</a></h3><p>Before starting this section, please follow the instructions in <a href="#anchor_2_2">2.2 APP Installation and Connection</a> to complete the installation and connect the device.</p><h3 id="_2-3-2-button-function" tabindex="-1">2.3.2 Button Function <a class="header-anchor" href="#_2-3-2-button-function" aria-label="Permalink to &quot;2.3.2 Button Function&quot;">​</a></h3><ul><li><strong>Normal Mode</strong></li></ul><p>The app offers three operation modes: <strong>Normal Mode</strong>, <strong>Football Mode</strong>, and <strong>Fighting Mode</strong>. By default, the app starts in Normal Mode. The table below explains the button functions in Normal Mode as an example. The other modes work in a similar way, and functions with the same icon can be referenced here.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:left;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="320" src="'+l+'" width="150px"></td><td style="text-align:left;">Drag upward to make the robot walk forward, drag downward to walk backward, drag left to move left, and drag right to move right.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="126" src="'+r+'" width="150px"></td><td style="text-align:left;">Tap the left button to make the robot move left, press and hold to turn left. Tap the right button to move right, press and hold to turn right.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="74" src="'+t+'" width="150px"></td><td style="text-align:left;">Open a settings menu with five options: <strong>Contact Us</strong>, <strong>Control Mode</strong>, <strong>Work Mode</strong>, <strong>Reset Data</strong>, and <strong>Cancel</strong>.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="231" src="'+u+'" width="150px"></td><td style="text-align:left;">Open the list of preloaded dance routines. After selecting a dance routine, the robot will immediately perform it.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="72" src="'+b+'" width="150px"></td><td style="text-align:left;">Tap to enter the device search list. Once the device is connected successfully, the Bluetooth icon will remain solid. Tap again to disconnect the device.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" src="'+f+'" width="150px"></td><td style="text-align:left;">Display the robot&#39;s current battery level.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="178" src="'+y+'" width="150px"></td><td style="text-align:left;">Tap to access and play action group files that have been downloaded to the robot.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="187" src="'+x+'" width="150px"></td><td style="text-align:left;">Executes one of the three preset actions: <strong>Cheer</strong>, <strong>Roll forward</strong>, or <strong>Roll backward</strong>.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="868" src="'+w+'" width="150px"></td><td style="text-align:left;">Tap to perform a predefined action once.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="126" src="'+v+'" width="150px"></td><td style="text-align:left;">Tap to enter voice command control mode.</td></tr></tbody></table><p>(1) Football Mode</p><p>① Tap the settings icon <img loading="lazy" height="74" width="77" src="'+t+'">, select <strong>Work Mode</strong> <img loading="lazy" height="170" src="'+e+'" width="150px">, then choose <strong>Football Mode</strong>.</p><img loading="lazy" height="572" width="1207" src="'+S+'" class="common_img"><p>② The app will automatically switch to the corresponding control interface, as shown below.</p><img loading="lazy" height="470" width="1000" src="'+z+'" class="common_img"><p>(2) Fighting Mode</p><p>① Tap the settings icon <img loading="lazy" height="74" src="'+t+'" width="70px">, select <strong>Work Mode</strong> <img loading="lazy" height="170" src="'+e+'" width="150px">, then choose <strong>Fighting Mode</strong>.</p><img loading="lazy" height="572" width="1207" src="'+E+'" class="common_img"><p>② The app will automatically switch to the corresponding control interface, as shown below.</p><img loading="lazy" height="470" width="1000" src="'+C+'" class="common_img"><h3 id="_2-3-3-group-control-optional" tabindex="-1">2.3.3 Group Control (Optional) <a class="header-anchor" href="#_2-3-3-group-control-optional" aria-label="Permalink to &quot;2.3.3 Group Control (Optional)&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Group dance control requires at least <strong>two</strong> RoboSoul H5S robots.</p></li><li><p>When controlling multiple robots simultaneously, to maintain stable performance and keep the formation neat, avoid using the forward/backward/left/right joystick controls <img loading="lazy" height="320" src="'+l+'" width="70px"> and the left/right turn buttons<img loading="lazy" height="126" src="'+r+'" width="150px">.</p></li></ul></div><p>(1) Turn on all robots.</p><p>(2) Connect to the devices named &quot;<strong>Robo-Soul</strong>&quot; following the same steps used for a single robot connection.</p><p>(3) Tap the menu icon <img loading="lazy" height="74" width="77" src="'+t+'"> in the upper-right corner, then tap <img loading="lazy" height="174" src="'+V+'" width="150px"> to select Control All.</p><img loading="lazy" height="589" width="1211" src="'+k+'" class="common_img"><p>(4) On the app interface, tap the central robot icon. If your app interface is different, tap the upper-right menu icon<img loading="lazy" height="74" width="77" src="'+t+'">, select <img loading="lazy" height="170" src="'+e+'" width="150px"> Normal Mode, and the interface will switch back.</p><p>(5) Tap the dance icon as shown, select the desired dance routine from the pop-up list, and all robots will begin the group dance performance.</p><img loading="lazy" height="469" width="1000" src="'+X+'" class="common_img">',52)])])}const j=i(K,[["render",W]]);export{O as __pageData,j as default};
